import json

animals = {
    "bee", "frog", "snake", "seahorse", "woodpecker",
    "swan", "beetle", "stork", "finch",
}
primary_colors = {"red", "green", "blue"}

# Facts explicitly stated in the problem.
facts = {
    ("card_color", "bee", "blue"),
    ("card_color", "frog", "yellow"),
    ("has_leafy_vegetable", "frog"),
    ("hours_reduced", "snake"),
    ("not_creates_vampire_castle", "seahorse"),
    ("not_tears_badger_castle", "bee"),
}

def close(disable_rule6=False):
    """Forward-chain the applicable rules over the finite set of named animals."""
    known = set(facts)

    def add(atom):
        if atom not in known:
            known.add(atom)
            return True
        return False

    changed = True
    while changed:
        changed = False

        def emit(atom):
            nonlocal changed
            changed |= add(atom)

        # Rule 23
        for animal in animals:
            if ("hours_reduced", animal) in known:
                emit(("tears_dove_castle", animal))

        # Rule 2
        if any(p == "tears_dove_castle" for p, *_ in known):
            emit(("takes_over_monkey_emperor", "woodpecker"))

        # Rule 13
        if any(p == "takes_over_monkey_emperor" for p, *_ in known):
            emit(("not_refuses_dinosaur_help", "bee"))

        # Rule 17
        for animal in animals:
            if ("not_refuses_dinosaur_help", animal) in known:
                emit(("reveals_secret_to_zebra", animal))

        # Rule 5
        for animal in animals:
            if ("not_tears_badger_castle", animal) in known:
                emit(("refuses_badger_help", animal))

        # Rule 19
        for animal in animals:
            if ("refuses_badger_help", animal) in known:
                emit(("shouts_dragonfly", animal))

        # Rules 20 and 14
        for animal in animals:
            if ("shouts_dragonfly", animal) in known:
                emit(("wants_fangtooth", animal))
            if ("wants_fangtooth", animal) in known:
                emit(("not_shouts_beetle", animal))

        # Rule 18
        for animal in animals:
            if (("not_shouts_beetle", animal) in known and
                    ("reveals_secret_to_zebra", animal) in known):
                emit(("not_trades_stork", animal))

        # Rule 21; Rule 11 has no age fact, and Rule 16 does not apply
        # because yellow is not one of the RGB primary colors.
        frog_color_is_primary = any(
            ("card_color", "frog", color) in known
            for color in primary_colors
        )
        frog_is_under_four = ("age_under_four", "frog") in known
        if ("has_leafy_vegetable", "frog") in known:
            if not frog_is_under_four and not frog_color_is_primary:
                emit(("destroys_swan_wall", "frog"))

        # Rule 24
        if ("destroys_swan_wall", "frog") in known:
            emit(("shouts_peafowl", "swan"))

        # Rule 6: its conclusion is defeated by preferred Rule 24 when
        # Rule 24's antecedent holds.
        if not disable_rule6 and any(
            p == "enjoys_ant" for p, *_ in known
        ):
            emit(("not_shouts_peafowl", "swan"))

        # Rule 12
        for animal in animals:
            if ("not_creates_vampire_castle", animal) in known:
                emit(("enjoys_ant", animal))

        # Rule 22, then Rule 1
        for animal in animals:
            if ("shouts_peafowl", animal) in known:
                emit(("shouts_beaver", animal))
            if ("shouts_beaver", animal) in known:
                emit(("unites_ostrich", animal))

        # Rule 7
        if any(p == "unites_ostrich" for p, *_ in known):
            emit(("trades_stork", "beetle"))

        # Rule 4
        if (("not_trades_stork", "bee") in known and
                ("trades_stork", "beetle") in known):
            emit(("wants_goat", "stork"))

        # Rule 10
        if any(p == "wants_goat" for p, *_ in known):
            emit(("not_captures_pigeon_king", "finch"))

    return known

# First determine whether the preferred Rule 24 applies. If so, recompute
# without Rule 6's defeated conclusion.
probe = close()
rule24_applies = ("destroys_swan_wall", "frog") in probe
known = close(disable_rule6=rule24_applies)

positive = ("captures_pigeon_king", "finch") in known
negative = ("not_captures_pigeon_king", "finch") in known

if positive and not negative:
    answer = "proved"
elif negative and not positive:
    answer = "disproved"
elif not positive and not negative:
    answer = "unknown"
else:
    # Conflicting unresolved conclusions would not settle the truth value.
    answer = "unknown"

evidence = []
chain = [
    ("tears_dove_castle", "snake"),
    ("takes_over_monkey_emperor", "woodpecker"),
    ("not_refuses_dinosaur_help", "bee"),
    ("reveals_secret_to_zebra", "bee"),
    ("refuses_badger_help", "bee"),
    ("shouts_dragonfly", "bee"),
    ("wants_fangtooth", "bee"),
    ("not_shouts_beetle", "bee"),
    ("not_trades_stork", "bee"),
    ("destroys_swan_wall", "frog"),
    ("shouts_peafowl", "swan"),
    ("shouts_beaver", "swan"),
    ("unites_ostrich", "swan"),
    ("trades_stork", "beetle"),
    ("wants_goat", "stork"),
    ("not_captures_pigeon_king", "finch"),
]
for atom in chain:
    if atom in known:
        evidence.append(f"{atom[0]}({atom[1]})")

print(json.dumps({"final_answer": answer, "evidence": evidence}))
