edges = []
current = None
for command, xs, ys in commands:
    point = (float(xs), float(ys))
    if command == "M":
        current = point
    else:
        edges.append((current, point))
        current = point

# Coordinates are rounded in the question; use a small geometric tolerance.
TOL = 2e-4

def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])

def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]

def dot(a, b):
    return a[0] * b[0] + a[1] * b[1]

def norm(a):
    return math.hypot(a[0], a[1])

def near_zero(x, scale=1.0):
    return abs(x) <= TOL * max(1.0, scale)

# Build the endpoint graph.
points = sorted({p for edge in edges for p in edge})
index = {p: i for i, p in enumerate(points)}
adj = [set() for _ in points]
for a, b in edges:
    i, j = index[a], index[b]
    if i != j:
        adj[i].add(j)
        adj[j].add(i)

# Exhaustively enumerate simple graph cycles, once per orientation/start vertex.
cycles = set()
def walk(start, here, path_nodes, used):
    for nxt in adj[here]:
        if nxt == start and len(path_nodes) >= 3:
            if path_nodes[1] < path_nodes[-1]:
                cycles.add(tuple(path_nodes))
        elif nxt > start and nxt not in used:
            used.add(nxt)
            path_nodes.append(nxt)
            walk(start, nxt, path_nodes, used)
            path_nodes.pop()
            used.remove(nxt)

for start in range(len(points)):
    walk(start, start, [start], {start})

def simplify(poly):
    """Remove intermediate collinear points, including rounded-collinear ones."""
    out = list(poly)
    changed = True
    while changed and len(out) > 3:
        changed = False
        keep = []
        n = len(out)
        for i, p in enumerate(out):
            a, b = out[i - 1], out[(i + 1) % n]
            u, v = sub(p, a), sub(b, p)
            if near_zero(cross(u, v), norm(u) * norm(v)) and dot(u, v) >= -TOL:
                changed = True
            else:
                keep.append(p)
        out = keep
    return out

def area2(poly):
    return sum(cross(poly[i], poly[(i + 1) % len(poly)])
               for i in range(len(poly)))

def orient(a, b, c):
    return cross(sub(b, a), sub(c, a))

def on_segment(a, b, p):
    return (abs(orient(a, b, p)) <= TOL * max(1.0, norm(sub(b, a))) and
            min(a[0], b[0]) - TOL <= p[0] <= max(a[0], b[0]) + TOL and
            min(a[1], b[1]) - TOL <= p[1] <= max(a[1], b[1]) + TOL)

def segments_intersect(a, b, c, d):
    o1, o2 = orient(a, b, c), orient(a, b, d)
    o3, o4 = orient(c, d, a), orient(c, d, b)
    if ((o1 > TOL and o2 < -TOL) or (o1 < -TOL and o2 > TOL)) and \
       ((o3 > TOL and o4 < -TOL) or (o3 < -TOL and o4 > TOL)):
        return True
    return (on_segment(a, b, c) or on_segment(a, b, d) or
            on_segment(c, d, a) or on_segment(c, d, b))

def simple_polygon(poly):
    n = len(poly)
    for i in range(n):
        a, b = poly[i], poly[(i + 1) % n]
        for j in range(i + 1, n):
            if j == i or j == (i + 1) % n or i == (j + 1) % n:
                continue
            c, d = poly[j], poly[(j + 1) % n]
            if segments_intersect(a, b, c, d):
                return False
    return True

def point_in_polygon(p, poly):
    inside = False
    x, y = p
    for i, a in enumerate(poly):
        b = poly[(i + 1) % len(poly)]
        if on_segment(a, b, p):
            return True
        if (a[1] > y) != (b[1] > y):
            x_cross = a[0] + (y - a[1]) * (b[0] - a[0]) / (b[1] - a[1])
            if x < x_cross:
                inside = not inside
    return inside

def drawn_diagonal(a, b):
    """True if input segments cover the full straight segment from a to b."""
    v = sub(b, a)
    vv = dot(v, v)
    if vv == 0:
        return False
    intervals = []
    for p, q in edges:
        if (abs(orient(a, b, p)) <= TOL * max(1.0, norm(v)) and
            abs(orient(a, b, q)) <= TOL * max(1.0, norm(v))):
            t1, t2 = dot(sub(p, a), v) / vv, dot(sub(q, a), v) / vv
            lo, hi = sorted((t1, t2))
            lo, hi = max(0.0, lo), min(1.0, hi)
            if hi >= lo - TOL:
                intervals.append((lo, hi))
    intervals.sort()
    end = 0.0
    for lo, hi in intervals:
        if lo > end + TOL:
            return False
        end = max(end, hi)
        if end >= 1.0 - TOL:
            return True
    return False

def has_diagonal(poly):
    n = len(poly)
    for i in range(n):
        for j in range(i + 1, n):
            if j == i + 1 or (i == 0 and j == n - 1):
                continue
            if drawn_diagonal(poly[i], poly[j]):
                return True
    return False

def parallel(a, b):
    return abs(cross(a, b)) <= TOL * max(1.0, norm(a) * norm(b))

def regular(poly):
    n = len(poly)
    sides = [sub(poly[(i + 1) % n], poly[i]) for i in range(n)]
    lengths = [norm(v) for v in sides]
    if max(lengths) - min(lengths) > TOL * max(1.0, max(lengths)):
        return False
    turns = [abs(math.atan2(cross(sides[i - 1], sides[i]),
                            dot(sides[i - 1], sides[i])))
             for i in range(n)]
    return max(turns) - min(turns) <= 1e-3

def classify(poly):
    n = len(poly)
    sides = [sub(poly[(i + 1) % n], poly[i]) for i in range(n)]
    turns = [orient(poly[i], poly[(i + 1) % n], poly[(i + 2) % n])
             for i in range(n)]
    convex = all(x >= -TOL for x in turns) or all(x <= TOL for x in turns)

    if n == 3:
        right = any(near_zero(dot(sub(poly[(i - 1) % 3], poly[i]),
                                  sub(poly[(i + 1) % 3], poly[i])),
                              norm(sub(poly[(i - 1) % 3], poly[i])) *
                              norm(sub(poly[(i + 1) % 3], poly[i])))
                    for i in range(3))
        return 4 if right else 3

    if n == 4 and convex:
        p02 = parallel(sides[0], sides[2])
        p13 = parallel(sides[1], sides[3])
        parallelogram = p02 and p13
        rectangle = parallelogram and all(
            near_zero(dot(sides[i], sides[(i + 1) % 4]),
                      norm(sides[i]) * norm(sides[(i + 1) % 4]))
            for i in range(4)
        )
        if rectangle:
            lengths = [norm(v) for v in sides]
            return 2 if max(lengths) - min(lengths) <= TOL * max(lengths) else 1
        if parallelogram:
            return 5
        if p02 != p13:
            return 6
        return None

    if n == 5:
        if not convex:
            return 8
        return 9 if regular(poly) else 7

    if n == 6 and convex and regular(poly):
        return 10
    return None

found = set()
valid_polygons = set()
for cycle in cycles:
    poly = simplify([points[i] for i in cycle])
    if len(poly) < 3 or abs(area2(poly)) <= TOL or not simple_polygon(poly):
        continue
    if has_diagonal(poly):
        continue
    # Deduplicate identical polygons regardless of starting point/direction.
    rotations = []
    for seq in (poly, list(reversed(poly))):
        rotations.extend(tuple(seq[i:] + seq[:i]) for i in range(len(seq)))
    key = min(rotations)
    if key in valid_polygons:
        continue
    valid_polygons.add(key)
    category = classify(poly)
    if category is not None:
        found.add(category)

options = {
    "A": {1, 7, 3}, "B": {1, 8}, "C": {7, 9}, "D": {5},
    "E": {1, 5, 7, 8}, "F": {1, 5, 7, 8, 4, 6},
    "G": {7, 8, 2, 10}, "H": {1, 8, 9}, "I": {5, 3},
    "J": {1}, "K": {7, 8}, "L": {5, 8}, "M": {5, 2},
    "N": {1, 8, 2, 4, 9}, "O": {1, 5, 7, 8, 10},
    "P": {1, 7, 8, 6},
}
names = {
    1: "non-square rectangle", 2: "square", 3: "non-right triangle",
    4: "right triangle", 5: "non-rectangular parallelogram",
    6: "exactly-one-pair trapezoid", 7: "irregular convex pentagon",
    8: "irregular concave pentagon", 9: "regular pentagon",
    10: "regular hexagon",
}

matches = sorted(k for k, v in options.items() if v == found)
print("Graph vertices:", len(points), "segments:", len(edges))
print("Enumerated simple cycles:", len(cycles))
print("Detected categories:", sorted(found))
print("Detected shapes:", [names[i] for i in sorted(found)])
print("Matching option(s):", matches if matches else "none")
print("CHECK PASS" if found == options["E"] else "CHECK FAIL")
