def opposite(atom):
    pairs = {
        "build": "not_build", "not_build": "build",
        "shout": "not_shout", "not_shout": "shout",
        "smile": "not_smile", "not_smile": "smile",
        "call": "not_call", "not_call": "call",
    }
    pred, *args = atom
    return (pairs[pred], *args) if pred in pairs else None

def applicable_rules(known):
    rules = [
        ("R1", {
            ("negotiates", "ant", "stork"),
            ("not_trade", "dalmatian", "stork"),
        }, ("build", "stork")),
    ]

    for animal in animals:
        rules.append((
            "R2", {("build", animal)}, ("not_shout", "mouse", "beetle")
        ))
        rules.append((
            "R5",
            {("hugs", animal, "dinosaur"), ("smile", animal, "cobra")},
            ("shout", animal, "beetle"),
