    if ("has_instrument", "llama") in known:
        rules.append(("R6", {("has_instrument", "llama")}, ("call", "llama", "husky")))
    if any(len(a) == 3 and a[0] == "photo" and a[2] == "fish" for a in known):
        rules.append(("R8", {("photo", "dragon", "fish")}, ("not_call", "llama", "husky")))

    # Rule3's money comparison is included only when both amounts are known.
    money = {a[1]: a[2] for a in known if len(a) == 3 and a[0] == "money"}
    if "stork" in money and "walrus" in money and money["stork"] > money["walrus"]:
        rules.append(("R3", set(), ("not_build", "stork")))

    return [r for r in rules if r[1] <= known]

known = set(facts)
