def evaluate(node):
    if isinstance(node, ast.Expression):
        return evaluate(node.body)
    if isinstance(node, ast.Constant) and isinstance(node.value, (bool, int)):
        return node.value
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
        return not evaluate(node.operand)
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.USub):
        return -evaluate(node.operand)
    if isinstance(node, ast.BinOp):
        left, right = evaluate(node.left), evaluate(node.right)
        operations = {
            ast.Add: operator.add,
            ast.Sub: operator.sub,
            ast.Mult: operator.mul,
            ast.Div: operator.truediv,
        }
        operation = operations.get(type(node.op))
        if operation is None:
            raise ValueError("Unsupported arithmetic operator")
        if isinstance(node.op, ast.Div):
            left, right = Fraction(left), Fraction(right)
        return operation(left, right)
    if isinstance(node, ast.BoolOp):
        values = [evaluate(value) for value in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        if isinstance(node.op, ast.Or):
            return any(values)
        raise ValueError("Unsupported Boolean operator")
    if isinstance(node, ast.Compare):
        left = evaluate(node.left)
        for op, comparator in zip(node.ops, node.comparators):
            right = evaluate(comparator)
            operations = {
                ast.Gt: operator.gt,
                ast.Lt: operator.lt,
                ast.GtE: operator.ge,
                ast.LtE: operator.le,
                ast.Eq: operator.eq,
                ast.NotEq: operator.ne,
            }
            operation = operations.get(type(op))
            if operation is None or not operation(left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
        args = [evaluate(arg) for arg in node.args]
        if node.func.id == "max":
            return max(args)
        if node.func.id == "min":
            return min(args)
    if isinstance(node, ast.Name) and node.id in ("True", "False"):
        return node.id == "True"
    raise ValueError("Unsupported expression: " + ast.dump(node))

def prepare(source):
    for proposition, value in facts.items():
        source = source.replace(proposition, value)
    for phrase, symbol in (
        ("is less than or equal to", "<="),
        ("is greater than or equal to", ">="),
        ("is greater than", ">"),
    ):
        source = source.replace(phrase, symbol)
    return source

try:
    results = {}
    for letter, source in expressions.items():
        tree = ast.parse(prepare(source), mode="eval")
        results[letter] = bool(evaluate(tree))

    print("Option values:", ", ".join(f"{k}={v}" for k, v in results.items()))
    true_options = [k for k, v in results.items() if v]
    print("True option(s):", true_options)

    if len(true_options) == 1:
        print("Uniqueness check: CHECK PASS")
    else:
        print("Uniqueness check: CHECK FAIL")

    # The submitted response does not name an option.
    print("Submitted answer check: CHECK FAIL (no option letter is identified)")
except Exception as error:
    print("UNSUPPORTED:", error)
