from fractions import Fraction as F
from math import gcd, lcm
from decimal import Decimal, getcontext
import json

# Represent a + b*sqrt(39) exactly, with rational a and b.
class Q:
    def __init__(self, a=0, b=0):
        self.a, self.b = F(a), F(b)

    def __add__(self, other):
        other = as_q(other)
        return Q(self.a + other.a, self.b + other.b)

    __radd__ = __add__

    def __neg__(self):
        return Q(-self.a, -self.b)

    def __sub__(self, other):
        return self + (-as_q(other))

    def __rsub__(self, other):
        return as_q(other) - self

    def __mul__(self, other):
        other = as_q(other)
        return Q(self.a * other.a + 39 * self.b * other.b,
                 self.a * other.b + self.b * other.a)

    __rmul__ = __mul__

    def __truediv__(self, other):
        other = as_q(other)
        norm = other.a * other.a - 39 * other.b * other.b
        assert norm != 0
        return Q((self.a * other.a - 39 * self.b * other.b) / norm,
                 (self.b * other.a - self.a * other.b) / norm)


def as_q(value):
    return value if isinstance(value, Q) else Q(value)


def sign(q):
    """Exact sign of a + b*sqrt(39)."""
    a, b = q.a, q.b
    if b == 0:
        return (a > 0) - (a < 0)
    if a == 0:
        return (b > 0) - (b < 0)
    if a > 0 and b > 0:
        return 1
    if a < 0 and b < 0:
        return -1
    if a > 0:  # a > 0, b < 0
        return (a * a > 39 * b * b) - (a * a < 39 * b * b)
    # a < 0, b > 0
    return (39 * b * b > a * a) - (39 * b * b < a * a)


def decimal_value(q):
    return (Decimal(q.a.numerator) / Decimal(q.a.denominator)
            + (Decimal(q.b.numerator) / Decimal(q.b.denominator))
            * Decimal(39).sqrt())


def exact_string(q):
    # Common-denominator form, assembled from the computed coefficients.
    den = lcm(q.a.denominator, q.b.denominator)
    a = q.a.numerator * (den // q.a.denominator)
    b = q.b.numerator * (den // q.b.denominator)
    common = gcd(gcd(abs(a), abs(b)), den)
    a, b, den = a // common, b // common, den // common
    if b == 0:
        return str(F(a, den))
    if a == 0:
        numerator = f"{b}*sqrt(39)"
    else:
        numerator = f"{a} {'+' if b > 0 else '-'} {abs(b)}*sqrt(39)"
    return f"({numerator})/{den}"


# On the closed nonnegative feasible set, xyz attains a maximum.
# At an interior extremum, Lagrange multipliers give
# (y-x)(z-mu)=0 and its cyclic versions, so at least two variables
# are equal (the all-distinct case would force x=y=z, impossible here).
# Boundary points have xyz=0. Thus it suffices to check the boundary
# and the feasible two-equal candidates.
two = Q(3)
candidates = []
for a in (Q(3, F(1, 3)), Q(3, F(-1, 3))):
    b = Q(9) - 2 * a
    if sign(a) > 0 and sign(b) > 0:
        assert a * a + 2 * a * b == Q(14)
        assert 2 * a + b == Q(9)
        candidates.append((a, b, a * a * b))

assert candidates
best_r = Q(0)  # boundary
best = None
for a, b, r in candidates:
    if sign(r - best_r) > 0:
        best_r, best = r, (a, b)

# The objective is 36 - 2660/(126-xyz), hence decreases as xyz increases.
answer = Q(36) - Q(2660) / (Q(126) - best_r)

getcontext().prec = 30
a, b = best
evidence = {
    "method": "Reduce the objective to a decreasing function of xyz; check boundary and all feasible two-equal stationary candidates.",
    "minimizing_triple": [str(decimal_value(a)), str(decimal_value(a)), str(decimal_value(b))],
    "maximum_xyz": exact_string(best_r),
    "objective_decimal": str(decimal_value(answer)),
}
print(json.dumps({"final_answer": exact_string(answer), "evidence": evidence}))
