import itertools
import json

riders = ("Reynaldo", "Seamus", "Theresa", "Yuki")
bikes = ("F", "G", "H", "J")
options = {key: 0 for key in "ABCDE"}
models = 0

for day1_values in itertools.permutations(bikes):
    day1 = dict(zip(riders, day1_values))
    if day1["Reynaldo"] == "F" or day1["Yuki"] == "J":
        continue
    if day1["Theresa"] != "J":
        continue

    for day2_values in itertools.permutations(bikes):
        day2 = dict(zip(riders, day2_values))
        if day2["Reynaldo"] == "F" or day2["Yuki"] == "J":
            continue
        if any(day1[rider] == day2[rider] for rider in riders):
            continue
        if day1["Yuki"] != day2["Seamus"]:
            continue
        if "H" not in (day1["Theresa"], day2["Theresa"]):
            continue

        models += 1
        truths = {
            "A": day2["Reynaldo"] == "G",
            "B": day1["Seamus"] == "H",
            "C": day2["Yuki"] == "H",
            "D": "J" in (day1["Seamus"], day2["Seamus"]),
            "E": "G" in (day1["Theresa"], day2["Theresa"]),
        }
        for key, is_true in truths.items():
            if is_true:
                options[key] += 1

possible = [key for key, count in options.items() if count]
answer = possible[0] if len(possible) == 1 else "UNSUPPORTED"

print(json.dumps({
    "final_answer": answer,
    "evidence": {"valid_assignments": models, "option_counts": options}
}))
