from itertools import permutations

riders = ("Reynaldo", "Seamus", "Theresa", "Yuki")
bikes = ("F", "G", "H", "J")
valid_schedules = []

# Each permutation assigns every rider a different bicycle that day.
for first_perm in permutations(bikes):
    day1 = dict(zip(riders, first_perm))

    if day1["Theresa"] != "J":
        continue
    if day1["Reynaldo"] == "F" or day1["Yuki"] == "J":
        continue

    for second_perm in permutations(bikes):
        day2 = dict(zip(riders, second_perm))

        if any(day1[rider] == day2[rider] for rider in riders):
            continue
        if day2["Reynaldo"] == "F" or day2["Yuki"] == "J":
            continue
        if "H" not in (day1["Theresa"], day2["Theresa"]):
            continue
        if day2["Seamus"] != day1["Yuki"]:
            continue

        valid_schedules.append((day1, day2))

options = {
    "A": lambda d1, d2: d2["Reynaldo"] == "G",
    "B": lambda d1, d2: d1["Seamus"] == "H",
    "C": lambda d1, d2: d2["Yuki"] == "H",
    "D": lambda d1, d2: "J" in (d1["Seamus"], d2["Seamus"]),
    "E": lambda d1, d2: "G" in (d1["Theresa"], d2["Theresa"]),
}

possible = {}
witnesses = {}
for label, condition in options.items():
    matching = [(d1, d2) for d1, d2 in valid_schedules if condition(d1, d2)]
    possible[label] = bool(matching)
    if matching:
        witnesses[label] = matching[0]

print("Valid schedules:", len(valid_schedules))
print("Options that could be true:", [label for label in options if possible[label]])

for label in options:
    if label in witnesses:
        d1, d2 = witnesses[label]
        print(f"Witness for {label}: day 1 {d1}; day 2 {d2}")
    else:
        print(f"Option {label}: impossible")

if possible["A"]:
    print("CHECK PASS: submitted answer A could be true.")
else:
    correct = [label for label in options if possible[label]]
    if len(correct) == 1:
        print(f"CHECK FAIL: submitted answer A is impossible; the unique answer is {correct[0]}.")
    else:
        print("CHECK FAIL: submitted answer A is impossible.")
